css:
*{box-sizing:border-box}html,body{margin:0;background:#f7f5f0;color:#141313;font-family:'IPAGothic','IPAPGothic',sans-serif}
.sheet{width:3508px;height:2480px;padding:56px 64px;display:grid;grid-template-rows:auto 1fr;gap:28px}
header{display:flex;align-items:baseline;gap:36px;border-bottom:6px solid #141313;padding-bottom:14px}
header h1{font-size:76px;margin:0;letter-spacing:.04em}header .id{font-size:34px;color:#666}
header .heads{margin-left:auto;font-size:38px;color:#d23a26;font-weight:bold}
.grid{display:grid;gap:44px;min-height:0}.grid.main{grid-template-columns:2300px 1fr}.grid.detail{grid-template-columns:2500px 1fr}.grid>section{min-width:0;overflow:hidden}
h2{font-size:32px;margin:0 0 12px;border-left:12px solid #d23a26;padding-left:12px}
.turn{position:relative;display:flex;justify-content:space-around;align-items:flex-end;gap:24px;margin:40px 0 0 56px;border-bottom:3px solid #141313}
.view{margin:0;text-align:center;position:relative;z-index:1}.view img{display:block}
.view figcaption{font-size:28px;margin-top:6px}
.view.empty{flex:0 0 400px;width:400px;height:100%;border:4px dashed #bbb;display:flex;align-items:center;justify-content:center;font-size:32px;color:#999}
.guide{position:absolute;left:-56px;right:0;border-top:2px dashed rgba(210,58,38,.55);z-index:0}
.guide b{position:absolute;left:0;top:-18px;font-size:26px;color:#d23a26}
.guide.end{border-top-style:solid}
.exprs{display:grid;grid-template-columns:repeat(3,320px);gap:14px}
.exprs figure,.details figure{margin:0;text-align:center}.exprs img{width:320px;height:320px;border:3px solid #141313}
.exprs figcaption,.details figcaption{font-size:26px}
.details{display:grid;grid-template-columns:repeat(3,320px);gap:14px;margin-top:24px}.details img{width:320px;height:320px;border:3px solid #141313}
table{border-collapse:collapse;font-size:24px;width:100%}th,td{border:2px solid #141313;padding:6px 8px;text-align:left;font-family:monospace}
th{font-family:'IPAGothic',sans-serif}td i{display:inline-block;width:40px;height:28px;vertical-align:middle;margin-right:8px;border:1px solid #141313}
thead th{background:#141313;color:#f7f5f0}
ul{margin:0;padding-left:30px;font-size:26px;line-height:1.5}.side section{margin-bottom:26px}
.lack li{color:#d23a26}.empty{color:#999;font-size:28px}
.line{max-width:100%;max-height:520px;border:3px solid #141313}
.words{font-size:22px;color:#444;font-family:monospace;word-break:break-word}
header .page{font-size:34px;color:#141313;border:3px solid #141313;padding:2px 14px}.exprs.big{grid-template-columns:repeat(4,600px);gap:24px}.exprs.big img{width:600px;height:600px}.details.big{grid-template-columns:repeat(3,800px);gap:24px}.details.big img{width:800px;height:800px}.line{max-height:1900px}
